#!/usr/bin/env python3

def decode_sound_pattern(filename):
    with open(filename, 'r') as f:
        content = f.read().strip()

    # Define the sounds
    sounds = {
        'rooster': 'cock-a-doodle-do',
        'pig': 'oink',
        'cow': 'moo',
        'sheep': 'baa'
    }

    # Detect which animal sound is in the file
    animal_sound = None
    for animal, sound in sounds.items():
        if sound.lower() in content.lower():
            animal_sound = sound.lower()
            break

    if not animal_sound:
        return None

    # Split by the animal sound and get space lengths
    parts = content.split(animal_sound)
    space_lengths = [len(part.strip()) for part in parts[:-1]]

    # Convert space lengths to a string representation
    pattern = []
    for length in space_lengths:
        if length == 0:
            pattern.append('.')
        elif length == 1:
            pattern.append('-')
        elif length == 2:
            pattern.append(' ')
        else:
            pattern.append('_' * length)

    return ''.join(pattern)

# Analyze each file
for animal in ['rooster', 'pig', 'cow', 'sheep']:
    try:
        pattern = decode_sound_pattern(animal)
        if pattern:
            print(f"{animal}: {pattern}")
            print(f"Length: {len(pattern)}")
            print("Pattern chunks:", [pattern[i:i+8] for i in range(0, len(pattern), 8)])
            print()
    except Exception as e:
        print(f"Error with {animal}: {str(e)}")
        continue

