def decode_sound_to_morse(filename):
    with open(filename, 'r') as f:
        content = f.read().strip().lower()

    # Define the sounds
    sounds = {
        'rooster': 'cock-a-doodle-do',
        'pig': 'oink',
        'cow': 'moo',
        'sheep': 'baa'
    }

    # Detect which animal sound is in the file
    animal_sound = None
    for animal, sound in sounds.items():
        if sound.lower() in content.lower():
            animal_sound = sound.lower()
            break

    if not animal_sound:
        return None

    # Convert the pattern to dots and dashes
    morse = ""
    parts = content.split(animal_sound)
    for part in parts[:-1]:  # Skip last part
        spaces = len(part.strip())
        if spaces == 0:
            morse += "."
        elif spaces == 1:
            morse += "-"
        elif spaces == 3:
            morse += " "

    # Split into morse code characters
    morse_chars = morse.strip().split(" ")

    # Decode morse to text
    text = ""
