def analyze_farm_sounds():
    animals = ['rooster', 'pig', 'cow', 'sheep']
    sounds = {
        'rooster': 'cock-a-doodle-do',
        'pig': 'oink',
        'cow': 'moo',
        'sheep': 'baa'
    }

    results = []
    for animal in animals:
        try:
            with open(animal, 'r') as f:
                content = f.read().strip().lower()

            # Get the sound for this animal
            sound = sounds[animal]

            # Split by the sound
            parts = content.split(sound)

            # Analyze spacings between sounds
            spaces = [len(part.strip()) for part in parts[:-1]]

            # Get unique space lengths
            unique_spaces = sorted(list(set(spaces)))

            # Count occurrences of each space length
            space_counts = {length: spaces.count(length) for length in unique_spaces}

            # Create a pattern based on unique lengths
            pattern = []
            for space in spaces:
                if space == min(unique_spaces, default=0):
                    pattern.append('0')
                else:
                    pattern.append('1')

            # Group pattern into bytes
            bytes_pattern = []
            for i in range(0, len(pattern), 8):
                byte = pattern[i:i+8]
                if len(byte) == 8:
                    bytes_pattern.append(''.join(byte))

            results.append({
                'animal': animal,
                'unique_spaces': unique_spaces,
                'space_counts': space_counts,
                'total_sounds': len(spaces),
                'bytes': bytes_pattern
            })

        except Exception as e:
            print(f"Error processing {animal}: {str(e)}")
            continue

    return results

def main():
    results = analyze_farm_sounds()
    for result in results:
        print(f"\nAnalysis for {result['animal']}:")
        print(f"Unique space lengths: {result['unique_spaces']}")
        print(f"Space length counts: {result['space_counts']}")
