#!/usr/bin/env python3

def decode_sound_pattern(content, sound):
    # Remove any whitespace and newlines
    content = content.strip()

    # Split by sound pattern
    parts = content.split(sound)

    # Convert to binary based on spacing
    binary = ''
    for part in parts[:-1]:  # Skip last part after final sound
        spacing = len(part.strip())
        if spacing == 0:
            binary += '0'
        else:
            binary += '1'

    return binary

def main():
    animals = ['rooster', 'pig', 'cow', 'sheep']
    sounds = {
        'rooster': 'cock-a-doodle-do',
        'pig': 'oink',
        'cow': 'moo',
        'sheep': 'baa'
    }

    animal_patterns = {}

    # Read and decode each animal file
    for animal in animals:
        with open(animal, 'r') as f:
            content = f.read().lower()
        sound = sounds[animal]
        pattern = decode_sound_pattern(content, sound)
        animal_patterns[animal] = pattern

        print(f"\n{animal.upper()} Pattern Length: {len(pattern)}")
        print(f"Pattern: {pattern[:100]}...")

        # Try various decodings
        # Group into 8-bit chunks
        bytes_str = ''
        for i in range(0, len(pattern), 8):
            if i + 8 <= len(pattern):
                byte = pattern[i:i+8]
                try:
                    char = chr(int(byte, 2))
                    if char.isprintable():
                        bytes_str += char
                    else:
                        bytes_str += '.'
                except:
                    bytes_str += '.'

        print(f"ASCII attempt: {bytes_str[:100]}")

        # Try reverse bits
        rev_pattern = pattern[::-1]
        rev_str = ''
        for i in range(0, len(rev_pattern), 8):
            if i + 8 <= len(rev_pattern):
                byte = rev_pattern[i:i+8]
                try:
                    char = chr(int(byte, 2))
                    if char.isprintable():
                        rev_str += char
                    else:
                        rev_str += '.'
                except:
                    rev_str += '.'

        print(f"Reversed ASCII attempt: {rev_str[:100]}")

    # Try combining patterns
    combined = ''
    for i in range(min(len(p) for p in animal_patterns.values())):
        bits = ''
        for animal in animals:
            if i < len(animal_patterns[animal]):
                bits += animal_patterns[animal][i]
        if len(bits) == 4:  # We have all 4 animals
            try:
                char = chr(int(bits, 2))
                if char.isprintable():
                    combined += char
                else:
                    combined += '.'
            except:
                combined += '.'

    print("\nCombined patterns (4 bits from each animal):")
    print(combined)

    # Try other combinations like XOR of patterns
    xored = ''
    min_len = min(len(p) for p in animal_patterns.values())
    for i in range(0, min_len, 8):
        if i + 8 <= min_len:
            xor_result = 0
            for animal in animals:
                chunk = animal_patterns[animal][i:i+8]
                xor_result ^= int(chunk, 2)
            try:
                char = chr(xor_result)
                if char.isprintable():
                    xored += char
                else:
                    xored += '.'
            except:
                xored += '.'

    print("\nXORed patterns:")
    print(xored)

if __name__ == '__main__':
    main()
